/**
 * MASTER LANGUAGE LIST
 * Source: InterpretNext Master Language List (Localization, draft v1, 17 Nov 2026).
 * The rows live in languages.master.ts, generated by scripts/import-languages.py. Re-run the script
 * when the workbook changes; every language feature on the site (directory, checker, assistant,
 * quote form, homepage block) reads from here.
 *
 * Publication rule (from the workbook README):
 * - Once Operations fills "Staffable today" for any row, the site switches to strict mode: only rows
 *   marked "Yes - scheduled", "Yes - on demand" or "On request" are published, with real labels,
 *   and a public count is shown.
 * - Until then (agreed 19 Nov 2026) every row is searchable, each result says
 *   "Ask us to confirm availability", and no count is shown anywhere.
 */
import { MASTER } from "./languages.master";

export const REGIONS = [
  "Middle East & North Africa",
  "East Africa",
  "West Africa",
  "Central & Southern Africa",
  "South Asia",
  "Central Asia & Caucasus",
  "East & Southeast Asia",
  "Europe",
  "Americas",
  "Pacific & Oceania",
] as const;
export type Region = (typeof REGIONS)[number];

export type Availability = "scheduled" | "on-demand" | "on-request" | "no" | null;

export type MasterRow = {
  id: string;
  name: string;
  native?: string;
  iso: string;
  region: string;
  category: string;
  varieties: { code?: string; label: string }[];
  staffable: Availability;
  modes?: string;
  reviewed?: boolean;
  source?: "web";
  /** Added by the website team and waiting for Operations to confirm delivery (ASL). */
  confirm?: boolean;
};

export type Language = MasterRow & { region: Region; aka: string[] };

/** Extra search terms people type that are not in the list itself. Search only, never displayed. */
const AKA: Record<string, string[]> = {
  Arabic: ["MSA", "Darija", "Sudanese", "Egyptian", "Levantine", "Gulf", "Maghrebi"],
  "Persian (Farsi)": ["Persian", "Farsi"],
  "Mandarin Chinese": ["Chinese", "Mandarin", "Putonghua"],
  "Tagalog (Filipino)": ["Filipino", "Tagalog"],
  "American Sign Language": ["ASL", "Sign language", "Deaf"],
  "Central Atlas Tamazight": ["Tamazight", "Berber", "Amazigh"],
  Burmese: ["Myanmar"],
  Khmer: ["Cambodian"],
};

const isRegion = (r: string): r is Region => (REGIONS as readonly string[]).includes(r);

const ALL: Language[] = MASTER.filter((r) => isRegion(r.region)).map((r) => ({
  ...r,
  region: r.region as Region,
  aka: AKA[r.name] ?? [],
}));

/** True once Operations has filled "Staffable today" for at least one language. */
export const STRICT = ALL.some((l) => l.staffable !== null);

const PUBLISHABLE: Availability[] = ["scheduled", "on-demand", "on-request"];

export const LANGUAGES: Language[] = (STRICT ? ALL.filter((l) => PUBLISHABLE.includes(l.staffable)) : ALL).sort((a, b) =>
  a.name.localeCompare(b.name),
);

/** A public count only exists once availability is confirmed. Never show a number while this is null. */
export const PUBLIC_COUNT: number | null = STRICT ? LANGUAGES.length : null;

/** Rare, indigenous, creole and sign languages are flagged as harder to staff. */
export const isHardToStaff = (l: Language) => ["Rare", "Indigenous", "Creole & Pidgin"].includes(l.category);

