function norm(s: string) {
  return s.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/['’ʼ]/g, "").replace(/\s+/g, " ").trim();
}

/** Search by English name, native name, dialect, variety or country. Best matches first. */
export function searchLanguages(query: string): Language[] {
  const q = norm(query);
  if (!q) return [];
  const scored: { l: Language; s: number }[] = [];
  for (const l of LANGUAGES) {
    const name = norm(l.name);
    let s = 0;
    if (name === q) s = 100;
    else if (name.startsWith(q)) s = 80;
    else if (name.split(/[\s()/-]+/).some((w) => w && w.startsWith(q))) s = 70;
    else if (l.native && norm(l.native).includes(q)) s = 65;
    else if (l.aka.some((a) => norm(a).startsWith(q))) s = 60;
    else if (q.length >= 3 && name.includes(q)) s = 50;
    else if (q.length >= 3 && l.varieties.some((v) => norm(v.label).includes(q))) s = 30;
    if (s) scored.push({ l, s: s + (l.category === "Major" ? 2 : 0) });
  }
  return scored.sort((a, b) => b.s - a.s || a.l.name.localeCompare(b.l.name)).map((x) => x.l);
}

/** Exact or near-exact lookup for the assistant. */
export function findLanguage(query: string): Language | undefined {
  const q = norm(query);
  if (q.length < 2) return undefined;
  return searchLanguages(query).find((l) => {
    const name = norm(l.name);
    return name === q || name.startsWith(q + " ") || name.split(/[\s()/-]+/).includes(q) || l.aka.some((a) => norm(a) === q) || (l.native && norm(l.native) === q);
  });
}

/** Varieties that name a dialect or country, for display (codes stay internal). */
export const varietyText = (l: Language, max = 6) => {
  const labels = l.varieties.map((v) => v.label).filter((v) => v.toLowerCase() !== "diaspora");
  if (labels.length === 0) return "";
  return labels.length > max ? `${labels.slice(0, max).join(", ")} and ${labels.length - max} more` : labels.join(", ");
};

export function availabilityLabel(l: Language): string {
  switch (l.staffable) {
    case "scheduled":
      return "Scheduled sessions";
    case "on-demand":
      return "Scheduled sessions · On-demand coming";
    case "on-request":
      return "On request";
    default:
      return "Ask us to confirm availability";
  }
}

export function availabilityDetail(l: Language): string {
  switch (l.staffable) {
    case "scheduled":
    case "on-demand":
      return "Book a scheduled session through a quote. On-demand access is planned for a later release.";
    case "on-request":
      return "We source an interpreter for each request and confirm the lead time before you book.";
    default:
      return "Tell us the dialect, the date and the subject, and we will confirm whether we can staff it.";
  }
}

export const availabilityTone = (l: Language) => (l.staffable === "scheduled" || l.staffable === "on-demand" ? "success" : "violet");

export const regionSlug = (r: Region) => r.toLowerCase().replace(/&/g, "and").replace(/[^a-z]+/g, "-");
